"use client";

import React, { useEffect, useState, useCallback, useMemo } from "react";
import {
  MessageSquare, Search, RefreshCw, Filter, UserCheck, Clock,
  ShieldCheck, AlertTriangle, Send, Loader2, ArrowLeft,
  ChevronLeft, ChevronRight, Check, CheckCheck, XCircle, Info,
  Phone, User, Mail, ShieldAlert
} from "lucide-react";
import { fetchWithAuth } from "@/lib/fetchWithAuth";

// ─── Interfaces & Contract Types (SSOT with Step 5.9I) ───────────────────────

export interface ConversationItem {
  id: string;
  phone_e164: string;
  user_id: string | null;
  user_name: string | null;
  status: 'ACTIVE' | 'CLOSED' | 'ARCHIVED';
  unread_count: number;
  assigned_admin_id: string | null;
  assigned_admin_name: string | null;
  last_message_at: string;
  last_inbound_at: string | null;
  last_outbound_at: string | null;
  last_message_snippet: string | null;
  metadata: Record<string, any>;
}

export interface ConversationDetail extends ConversationItem {
  user: {
    id: string;
    name: string | null;
    email: string | null;
    mobile_number: string | null;
  } | null;
  assigned_admin: {
    id: string;
    name: string | null;
    email: string | null;
  } | null;
  created_at: string;
  updated_at: string;
}

export interface MessageItem {
  id: string;
  conversation_id: string;
  direction: 'INBOUND' | 'OUTBOUND';
  source: 'USER' | 'ADMIN' | 'SYSTEM' | 'AUTOMATION';
  message_type: 'TEXT' | 'TEMPLATE' | 'MEDIA' | 'INTERACTIVE';
  template_name: string | null;
  template_language: string | null;
  body: string | null;
  wamid: string | null;
  status: 'SENT' | 'DELIVERED' | 'READ' | 'FAILED';
  error_code: string | null;
  error_message: string | null;
  sent_at: string | null;
  delivered_at: string | null;
  read_at: string | null;
  failed_at: string | null;
  smart_alert_id: string | null;
  admin_sender_id: string | null;
  created_at: string;
}

export interface AdminUser {
  id: string;
  email: string;
  isAdmin: boolean;
  name?: string;
}

export interface WhatsAppCrmPanelProps {
  api: string;
  getAuthHeaders: () => Record<string, string>;
  triggerToast: (msg: string, type: "success" | "error" | "info") => void;
}

// ─── Pure Utility & Domain Helpers (Exported for Testability) ────────────────

const TWENTY_FOUR_HOURS_MS = 24 * 60 * 60 * 1000;

/**
 * Validates whether the 24-hour customer service window is open.
 * Fails closed on missing, null, or invalid dates.
 */
export function is24HourWindowActive(lastInboundAt: string | null | undefined, nowMs: number = Date.now()): boolean {
  if (!lastInboundAt || typeof lastInboundAt !== 'string') return false;
  const inboundTime = new Date(lastInboundAt).getTime();
  if (isNaN(inboundTime)) return false;
  const elapsed = nowMs - inboundTime;
  return elapsed >= 0 && elapsed <= TWENTY_FOUR_HOURS_MS;
}

/**
 * Returns a human-friendly duration remaining string for the 24h window.
 */
export function formatWindowRemaining(lastInboundAt: string | null | undefined, nowMs: number = Date.now()): string {
  if (!lastInboundAt || typeof lastInboundAt !== 'string') return "Expired (No inbound)";
  const inboundTime = new Date(lastInboundAt).getTime();
  if (isNaN(inboundTime)) return "Expired (Invalid date)";
  const remainingMs = TWENTY_FOUR_HOURS_MS - (nowMs - inboundTime);
  if (remainingMs <= 0) return "Expired (>24h)";
  const hours = Math.floor(remainingMs / (3600 * 1000));
  const minutes = Math.floor((remainingMs % (3600 * 1000)) / (60 * 1000));
  return `${hours}h ${minutes}m left`;
}

/**
 * Identifies whether a message payload contains protected OTP data.
 */
export function isProtectedOtp(message: { body?: string | null; template_name?: string | null; source?: string }): boolean {
  if (!message) return false;
  if (message.template_name === 'trayago_auth_otp') return true;
  if (message.source === 'AUTOMATION') return true;
  if (message.body === '[PROTECTED OTP]') return true;
  if (typeof message.body === 'string' && message.body.includes('[PROTECTED OTP]')) return true;
  return false;
}

/**
 * Builds the outbound message request payload. Strictly excludes admin_sender_id.
 */
export function buildAdminSendMessagePayload(text: string): { body: string } {
  return {
    body: (text || '').trim()
  };
}

/**
 * Builds the assignment payload.
 */
export function buildAssignmentPayload(adminId: string | null): { adminId: string | null } {
  const clean = typeof adminId === 'string' ? adminId.trim() : null;
  return {
    adminId: clean ? clean : null
  };
}

/**
 * Filters conversations locally (helper for search and fast previews).
 */
export function filterConversationsLocally(
  items: ConversationItem[],
  query: string,
  status: string,
  unreadOnly: boolean
): ConversationItem[] {
  return items.filter(conv => {
    if (status !== 'ALL' && conv.status !== status) return false;
    if (unreadOnly && (conv.unread_count || 0) <= 0) return false;
    if (query.trim()) {
      const q = query.trim().toLowerCase();
      const phoneMatch = (conv.phone_e164 || '').toLowerCase().includes(q);
      const nameMatch = (conv.user_name || '').toLowerCase().includes(q);
      const snippetMatch = (conv.last_message_snippet || '').toLowerCase().includes(q);
      if (!phoneMatch && !nameMatch && !snippetMatch) return false;
    }
    return true;
  });
}

// ─── Main Component ──────────────────────────────────────────────────────────

export function WhatsAppCrmPanel({ api, getAuthHeaders, triggerToast }: WhatsAppCrmPanelProps) {
  // State: Conversation List
  const [conversations, setConversations] = useState<ConversationItem[]>([]);
  const [totalConversations, setTotalConversations] = useState<number>(0);
  const [loadingConversations, setLoadingConversations] = useState<boolean>(true);
  const [selectedConvId, setSelectedConvId] = useState<string | null>(null);

  // State: Active Conversation & Messages
  const [activeDetail, setActiveDetail] = useState<ConversationDetail | null>(null);
  const [messages, setMessages] = useState<MessageItem[]>([]);
  const [loadingMessages, setLoadingMessages] = useState<boolean>(false);
  const [sendingMessage, setSendingMessage] = useState<boolean>(false);
  const [messageInput, setMessageInput] = useState<string>("");

  // State: Admin Users Directory (for assignment)
  const [adminUsers, setAdminUsers] = useState<AdminUser[]>([]);
  const [currentAdminId, setCurrentAdminId] = useState<string>("");
  const [assignmentLoading, setAssignmentLoading] = useState<boolean>(false);

  // State: Filters & Pagination
  const [searchPhone, setSearchPhone] = useState<string>("");
  const [statusFilter, setStatusFilter] = useState<'ACTIVE' | 'CLOSED' | 'ARCHIVED' | 'ALL'>('ACTIVE');
  const [unreadOnly, setUnreadOnly] = useState<boolean>(false);
  const [assignedFilter, setAssignedFilter] = useState<'all' | 'me' | 'unassigned'>('all');
  const [limit] = useState<number>(50);
  const [offset, setOffset] = useState<number>(0);

  // State: Operational Status
  const [serviceDisabledWarning, setServiceDisabledWarning] = useState<boolean>(false);

  // Extract current admin user ID on mount
  useEffect(() => {
    try {
      const user = JSON.parse(localStorage.getItem("user") || "{}");
      setCurrentAdminId(user.id || "");
    } catch {
      setCurrentAdminId("");
    }
  }, []);

  // 1. Fetch Authorized Administrators
  const fetchAdminUsers = useCallback(async () => {
    try {
      const res = await fetchWithAuth(`${api}/api/admin/users`, { headers: getAuthHeaders() });
      const json = await res.json();
      if (json.success && Array.isArray(json.data)) {
        const admins = json.data
          .filter((u: any) => u.isAdmin === true)
          .map((u: any) => ({
            id: u.id,
            email: u.email,
            isAdmin: true,
            name: (u.email || '').split('@')[0]
          }));
        setAdminUsers(admins);
      }
    } catch (err: any) {
      console.warn("[WHATSAPP_CRM] Admin user list fetch error:", err?.message);
    }
  }, [api, getAuthHeaders]);

  useEffect(() => {
    fetchAdminUsers();
  }, [fetchAdminUsers]);

  // 2. Fetch Conversations
  const fetchConversations = useCallback(async (isSilent: boolean = false) => {
    if (!isSilent) setLoadingConversations(true);
    try {
      const params = new URLSearchParams();
      params.set('limit', String(limit));
      params.set('offset', String(offset));
      if (statusFilter !== 'ALL') params.set('status', statusFilter);
      if (unreadOnly) params.set('unread_only', 'true');
      if (assignedFilter !== 'all') params.set('assigned_to', assignedFilter);
      if (searchPhone.trim()) params.set('search', searchPhone.trim());

      const res = await fetchWithAuth(`${api}/api/admin/whatsapp/conversations?${params.toString()}`, {
        headers: getAuthHeaders()
      });
      const json = await res.json();

      if (json.success) {
        setConversations(json.data || []);
        setTotalConversations(json.pagination?.total || 0);
      } else {
        triggerToast(json.error || "Failed to load conversations", "error");
        if (json.error && String(json.error).toLowerCase().includes('disabled')) {
          setServiceDisabledWarning(true);
        }
      }
    } catch {
      triggerToast("Network error loading WhatsApp conversations", "error");
    } finally {
      if (!isSilent) setLoadingConversations(false);
    }
  }, [api, getAuthHeaders, limit, offset, statusFilter, unreadOnly, assignedFilter, searchPhone, triggerToast]);

  useEffect(() => {
    fetchConversations();
  }, [fetchConversations]);

  // 3. Fetch Conversation Detail & Messages
  const selectConversation = useCallback(async (convId: string) => {
    setSelectedConvId(convId);
    setLoadingMessages(true);
    try {
      const [detailRes, msgRes] = await Promise.all([
        fetchWithAuth(`${api}/api/admin/whatsapp/conversations/${convId}`, { headers: getAuthHeaders() }),
        fetchWithAuth(`${api}/api/admin/whatsapp/conversations/${convId}/messages?limit=100`, { headers: getAuthHeaders() })
      ]);

      const detailJson = await detailRes.json();
      const msgJson = await msgRes.json();

      if (detailJson.success && detailJson.data) {
        setActiveDetail(detailJson.data);
      } else {
        triggerToast(detailJson.error || "Failed to load conversation details", "error");
      }

      if (msgJson.success && Array.isArray(msgJson.data)) {
        setMessages(msgJson.data);
      } else {
        triggerToast(msgJson.error || "Failed to load message history", "error");
      }
    } catch {
      triggerToast("Error retrieving conversation history", "error");
    } finally {
      setLoadingMessages(false);
    }
  }, [api, getAuthHeaders, triggerToast]);

  // 4. Update Admin Assignment
  const handleAssignmentChange = async (targetAdminId: string | null) => {
    if (!selectedConvId) return;
    setAssignmentLoading(true);

    try {
      const payload = buildAssignmentPayload(targetAdminId);
      const res = await fetchWithAuth(`${api}/api/admin/whatsapp/conversations/${selectedConvId}/assignment`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json", ...getAuthHeaders() },
        body: JSON.stringify(payload)
      });
      const json = await res.json();

      if (json.success && json.data) {
        triggerToast("Conversation assignment updated", "success");
        // Update detail in place
        setActiveDetail(prev => prev ? {
          ...prev,
          assigned_admin_id: json.data.assigned_admin_id,
          assigned_admin_name: json.data.assigned_admin_name
        } : null);
        // Update list in place
        setConversations(prev => prev.map(c => c.id === selectedConvId ? {
          ...c,
          assigned_admin_id: json.data.assigned_admin_id,
          assigned_admin_name: json.data.assigned_admin_name
        } : c));
      } else {
        triggerToast(json.error || "Assignment update failed", "error");
      }
    } catch {
      triggerToast("Network error updating assignment", "error");
    } finally {
      setAssignmentLoading(false);
    }
  };

  // 5. Send Admin Session Message
  const handleSendMessage = async () => {
    if (!selectedConvId || !activeDetail) return;
    const cleanText = messageInput.trim();
    if (!cleanText) return;

    // Usability Safeguard: Check 24-hour customer window
    const windowActive = is24HourWindowActive(activeDetail.last_inbound_at);
    if (!windowActive) {
      triggerToast("Cannot send message: 24-hour customer window is expired. Approved template required.", "error");
      return;
    }

    if (cleanText.length > 4096) {
      triggerToast("Message exceeds maximum length of 4096 characters", "error");
      return;
    }

    setSendingMessage(true);

    try {
      const payload = buildAdminSendMessagePayload(cleanText);
      const res = await fetchWithAuth(`${api}/api/admin/whatsapp/conversations/${selectedConvId}/messages`, {
        method: "POST",
        headers: { "Content-Type": "application/json", ...getAuthHeaders() },
        body: JSON.stringify(payload)
      });
      const json = await res.json();

      if (json.success) {
        triggerToast("WhatsApp message sent", "success");
        setMessageInput("");
        // Refresh message timeline
        const msgRes = await fetchWithAuth(`${api}/api/admin/whatsapp/conversations/${selectedConvId}/messages?limit=100`, {
          headers: getAuthHeaders()
        });
        const msgJson = await msgRes.json();
        if (msgJson.success && Array.isArray(msgJson.data)) {
          setMessages(msgJson.data);
        }
        // Refresh conversation list quietly
        fetchConversations(true);
      } else {
        triggerToast(json.error || "Failed to send message", "error");
        if (json.error && String(json.error).toLowerCase().includes('disabled')) {
          setServiceDisabledWarning(true);
        }
      }
    } catch {
      triggerToast("Network error sending WhatsApp message", "error");
    } finally {
      setSendingMessage(false);
    }
  };

  // Pagination navigation
  const handlePageChange = (direction: 'prev' | 'next') => {
    if (direction === 'prev' && offset > 0) {
      setOffset(Math.max(0, offset - limit));
    } else if (direction === 'next' && offset + limit < totalConversations) {
      setOffset(offset + limit);
    }
  };

  // 24h Window status for currently active conversation
  const isWindowOpen = useMemo(() => {
    return is24HourWindowActive(activeDetail?.last_inbound_at);
  }, [activeDetail?.last_inbound_at]);

  const windowRemaining = useMemo(() => {
    return formatWindowRemaining(activeDetail?.last_inbound_at);
  }, [activeDetail?.last_inbound_at]);

  return (
    <div className="space-y-4">
      {/* ── Operational Status Banner (When WhatsApp Service is Disabled) ── */}
      {serviceDisabledWarning && (
        <div className="bg-amber-500/10 border border-amber-500/20 rounded-xl p-3 flex items-center justify-between text-amber-400 text-xs animate-fade-in">
          <div className="flex items-center gap-2">
            <AlertTriangle size={15} className="text-amber-500 flex-shrink-0" />
            <span>
              <strong>WhatsApp Cloud API Offline:</strong> The backend WhatsApp service is currently disabled (ENABLE_WHATSAPP_SERVICE is off). Outbound messaging is paused.
            </span>
          </div>
          <button
            onClick={() => setServiceDisabledWarning(false)}
            className="text-[10px] uppercase font-bold text-muted hover:text-main px-2 py-1"
          >
            Dismiss
          </button>
        </div>
      )}

      {/* ── Master-Detail Cockpit Container ── */}
      <div className="h-[760px] bg-card border border-subtle rounded-2xl flex overflow-hidden shadow-sm">
        
        {/* ── Left Pane: Conversations List ── */}
        <div className={`w-full md:w-[380px] border-r border-subtle flex flex-col flex-shrink-0 bg-surface/40 ${selectedConvId ? 'hidden md:flex' : 'flex'}`}>
          {/* Header */}
          <div className="p-4 border-b border-subtle flex items-center justify-between">
            <div className="flex items-center gap-2">
              <MessageSquare className="text-emerald-400" size={18} />
              <h2 className="text-sm font-bold text-main">WhatsApp CRM</h2>
              <span className="text-[10px] font-mono px-1.5 py-0.5 rounded bg-input text-muted">
                {totalConversations}
              </span>
            </div>
            <button
              onClick={() => fetchConversations()}
              disabled={loadingConversations}
              title="Refresh conversation list"
              className="p-1.5 rounded-lg bg-input hover:bg-card border border-subtle text-secondary transition"
            >
              <RefreshCw size={13} className={loadingConversations ? "animate-spin" : ""} />
            </button>
          </div>

          {/* Search & Filters */}
          <div className="p-3 border-b border-subtle space-y-2">
            <div className="relative">
              <Search size={13} className="absolute left-2.5 top-2.5 text-muted" />
              <input
                type="text"
                placeholder="Search phone (+91...) or query"
                value={searchPhone}
                onChange={e => { setSearchPhone(e.target.value); setOffset(0); }}
                className="w-full bg-input border border-subtle rounded-lg pl-8 pr-3 py-1.5 text-xs text-main placeholder-muted focus:outline-none focus:border-strong transition"
              />
            </div>

            {/* Filter Pills */}
            <div className="flex items-center gap-1 overflow-x-auto pb-1 text-[11px]">
              {(['ACTIVE', 'CLOSED', 'ARCHIVED', 'ALL'] as const).map(st => (
                <button
                  key={st}
                  onClick={() => { setStatusFilter(st); setOffset(0); }}
                  className={`px-2 py-0.5 rounded-md font-medium transition ${
                    statusFilter === st
                      ? 'bg-primary text-white shadow-sm'
                      : 'bg-input text-secondary hover:text-main border border-subtle'
                  }`}
                >
                  {st}
                </button>
              ))}
            </div>

            <div className="flex items-center justify-between text-[11px] text-secondary pt-1">
              <label className="flex items-center gap-1.5 cursor-pointer">
                <input
                  type="checkbox"
                  checked={unreadOnly}
                  onChange={e => { setUnreadOnly(e.target.checked); setOffset(0); }}
                  className="rounded border-subtle text-primary focus:ring-0"
                />
                <span>Unread Only</span>
              </label>

              <select
                value={assignedFilter}
                onChange={e => { setAssignedFilter(e.target.value as any); setOffset(0); }}
                className="bg-input border border-subtle rounded px-2 py-0.5 text-[11px] text-main focus:outline-none"
              >
                <option value="all">All Assignments</option>
                <option value="me">Assigned to Me</option>
                <option value="unassigned">Unassigned</option>
              </select>
            </div>
          </div>

          {/* Conversations Scroll Area */}
          <div className="flex-1 overflow-y-auto divide-y divide-subtle/50">
            {loadingConversations ? (
              <div className="h-48 flex items-center justify-center">
                <Loader2 size={24} className="animate-spin text-primary" />
              </div>
            ) : conversations.length === 0 ? (
              <div className="p-8 text-center text-muted text-xs">
                <MessageSquare size={24} className="mx-auto mb-2 opacity-30" />
                <p>No conversations found</p>
                <p className="text-[10px] mt-1">Try resetting search filters</p>
              </div>
            ) : (
              conversations.map(conv => {
                const isSelected = conv.id === selectedConvId;
                const windowActive = is24HourWindowActive(conv.last_inbound_at);

                return (
                  <button
                    key={conv.id}
                    onClick={() => selectConversation(conv.id)}
                    className={`w-full text-left p-3.5 transition flex flex-col gap-1.5 ${
                      isSelected
                        ? 'bg-primary/10 border-l-4 border-primary'
                        : 'hover:bg-input/50'
                    }`}
                  >
                    <div className="flex items-center justify-between">
                      <span className="font-mono text-xs font-bold text-main truncate">
                        {conv.phone_e164}
                      </span>
                      <span className="text-[10px] text-muted">
                        {conv.last_message_at ? new Date(conv.last_message_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '—'}
                      </span>
                    </div>

                    <div className="flex items-center justify-between text-[11px]">
                      <span className="text-secondary truncate max-w-[200px]">
                        {conv.user_name || conv.last_message_snippet || "No messages yet"}
                      </span>
                      {conv.unread_count > 0 && (
                        <span className="bg-primary text-white text-[10px] font-black px-1.5 py-0.2 rounded-full min-w-[18px] text-center">
                          {conv.unread_count}
                        </span>
                      )}
                    </div>

                    <div className="flex items-center justify-between text-[10px] text-muted pt-0.5">
                      <span className="flex items-center gap-1 truncate max-w-[160px]">
                        <UserCheck size={11} className={conv.assigned_admin_id ? "text-emerald-400" : "text-muted"} />
                        <span className="truncate">{conv.assigned_admin_name || "Unassigned"}</span>
                      </span>

                      <span
                        title={windowActive ? "Customer service window open" : "Window expired: template required"}
                        className={`text-[9px] font-bold px-1.5 py-0.2 rounded flex items-center gap-1 ${
                          windowActive
                            ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20'
                            : 'bg-input text-muted'
                        }`}
                      >
                        <span className={`w-1.5 h-1.5 rounded-full ${windowActive ? 'bg-emerald-400' : 'bg-muted'}`} />
                        {windowActive ? "24h Window" : "Expired"}
                      </span>
                    </div>
                  </button>
                );
              })
            )}
          </div>

          {/* Pagination Footer */}
          <div className="p-2.5 border-t border-subtle flex items-center justify-between text-[11px] text-muted bg-card">
            <span>
              {totalConversations > 0 ? `${offset + 1}–${Math.min(offset + limit, totalConversations)} of ${totalConversations}` : "0 items"}
            </span>
            <div className="flex items-center gap-1">
              <button
                onClick={() => handlePageChange('prev')}
                disabled={offset === 0 || loadingConversations}
                className="p-1 rounded hover:bg-input disabled:opacity-30 transition"
              >
                <ChevronLeft size={14} />
              </button>
              <button
                onClick={() => handlePageChange('next')}
                disabled={offset + limit >= totalConversations || loadingConversations}
                className="p-1 rounded hover:bg-input disabled:opacity-30 transition"
              >
                <ChevronRight size={14} />
              </button>
            </div>
          </div>
        </div>

        {/* ── Right Pane: Active Chat Timeline & Composer ── */}
        <div className={`flex-1 flex flex-col bg-card ${selectedConvId ? 'flex' : 'hidden md:flex'}`}>
          {!selectedConvId || !activeDetail ? (
            <div className="flex-1 flex flex-col items-center justify-center p-8 text-center text-muted">
              <div className="p-4 bg-input rounded-full border border-subtle mb-3">
                <MessageSquare size={32} className="opacity-40" />
              </div>
              <h3 className="text-sm font-bold text-main">No Conversation Selected</h3>
              <p className="text-xs text-secondary max-w-sm mt-1">
                Select a conversation from the left to inspect customer details, chat history, or dispatch administrative responses.
              </p>
            </div>
          ) : (
            <>
              {/* Active Conversation Header */}
              <div className="p-4 border-b border-subtle bg-surface/30 flex flex-col sm:flex-row sm:items-center justify-between gap-3">
                <div className="flex items-center gap-3">
                  <button
                    onClick={() => setSelectedConvId(null)}
                    className="md:hidden p-1.5 rounded-lg bg-input text-secondary hover:text-main"
                  >
                    <ArrowLeft size={16} />
                  </button>
                  <div>
                    <div className="flex items-center gap-2">
                      <span className="font-mono text-sm font-bold text-main">{activeDetail.phone_e164}</span>
                      <span className="text-[10px] font-bold px-2 py-0.5 rounded bg-input border border-subtle text-secondary uppercase">
                        {activeDetail.status}
                      </span>
                    </div>
                    <div className="flex items-center gap-2 text-xs text-muted mt-0.5">
                      {activeDetail.user?.name && (
                        <span className="flex items-center gap-1 text-secondary">
                          <User size={11} /> {activeDetail.user.name}
                        </span>
                      )}
                      {activeDetail.user?.email && (
                        <span className="flex items-center gap-1 text-muted hidden sm:inline-flex">
                          <Mail size={11} /> {activeDetail.user.email}
                        </span>
                      )}
                    </div>
                  </div>
                </div>

                {/* Assignment & 24h Window Badge */}
                <div className="flex items-center gap-2 flex-wrap">
                  {/* 24h Window Indicator */}
                  <div
                    title={isWindowOpen ? "Customer sent inbound message within 24 hours" : "Window expired. Meta policy requires approved template to message."}
                    className={`px-2.5 py-1 rounded-lg text-xs font-semibold flex items-center gap-1.5 ${
                      isWindowOpen
                        ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20'
                        : 'bg-amber-500/10 text-amber-400 border border-amber-500/20'
                    }`}
                  >
                    <Clock size={12} />
                    <span>{isWindowOpen ? `🟢 Window: ${windowRemaining}` : "⚪ 24h Window Expired"}</span>
                  </div>

                  {/* Admin Assignment Selector */}
                  <div className="flex items-center gap-1.5 bg-input border border-subtle rounded-lg px-2 py-1">
                    <UserCheck size={13} className="text-muted" />
                    <select
                      value={activeDetail.assigned_admin_id || ""}
                      onChange={e => handleAssignmentChange(e.target.value ? e.target.value : null)}
                      disabled={assignmentLoading}
                      className="bg-transparent text-xs text-main font-medium focus:outline-none cursor-pointer"
                    >
                      <option value="" className="bg-card text-main">Unassigned</option>
                      {currentAdminId && (
                        <option value={currentAdminId} className="bg-card text-main">Assign to Me</option>
                      )}
                      {adminUsers
                        .filter(a => a.id !== currentAdminId)
                        .map(a => (
                          <option key={a.id} value={a.id} className="bg-card text-main">
                            Admin: {a.name || a.email}
                          </option>
                        ))}
                    </select>
                    {assignmentLoading && <Loader2 size={11} className="animate-spin text-muted" />}
                  </div>
                </div>
              </div>

              {/* Message Timeline */}
              <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-app/40">
                {loadingMessages ? (
                  <div className="h-full flex items-center justify-center">
                    <Loader2 size={28} className="animate-spin text-primary" />
                  </div>
                ) : messages.length === 0 ? (
                  <div className="h-full flex flex-col items-center justify-center text-muted text-xs">
                    <Info size={24} className="mb-2 opacity-30" />
                    <p>No messages recorded for this conversation container.</p>
                  </div>
                ) : (
                  messages.map(msg => {
                    const isInbound = msg.direction === 'INBOUND';
                    const hasProtectedOtp = isProtectedOtp(msg);

                    return (
                      <div
                        key={msg.id}
                        className={`flex flex-col ${isInbound ? 'items-start' : 'items-end'}`}
                      >
                        <div
                          className={`max-w-[85%] sm:max-w-md p-3 rounded-2xl shadow-sm text-xs select-text ${
                            isInbound
                              ? 'bg-input text-main border border-subtle rounded-tl-sm'
                              : 'bg-primary/15 text-main border border-primary/20 rounded-tr-sm'
                          }`}
                        >
                          {/* Message Header: Source & Template Tag */}
                          <div className="flex items-center justify-between gap-3 text-[10px] text-muted mb-1 pb-1 border-b border-subtle/40">
                            <span className="font-bold tracking-wider">
                              {isInbound ? "CUSTOMER" : (msg.source === 'ADMIN' ? "ADMIN REP" : msg.source)}
                            </span>
                            {msg.template_name && (
                              <span className="font-mono text-[9px] text-indigo-400">
                                {msg.template_name}
                              </span>
                            )}
                          </div>

                          {/* Message Body or Protected OTP Banner */}
                          {hasProtectedOtp ? (
                            <div className="flex items-center gap-2 p-2 bg-black/30 border border-subtle rounded-lg text-emerald-400 font-mono font-bold text-[11px]">
                              <ShieldCheck size={14} className="text-emerald-400 flex-shrink-0" />
                              <span>[PROTECTED OTP] (Redacted by Security Policy)</span>
                            </div>
                          ) : (
                            <p className="whitespace-pre-wrap break-words leading-relaxed">
                              {msg.body || "—"}
                            </p>
                          )}

                          {/* Message Footer: Timestamp & Delivery Status */}
                          <div className="flex items-center justify-end gap-1.5 text-[9px] text-muted mt-1.5 pt-0.5">
                            <span>
                              {msg.created_at ? new Date(msg.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : ''}
                            </span>
                            {!isInbound && (
                              <span title={`Status: ${msg.status}`}>
                                {msg.status === 'SENT' && <Check size={11} className="text-muted" />}
                                {msg.status === 'DELIVERED' && <CheckCheck size={11} className="text-secondary" />}
                                {msg.status === 'READ' && <CheckCheck size={11} className="text-emerald-400" />}
                                {msg.status === 'FAILED' && (
                                  <span className="flex items-center gap-0.5 text-danger font-bold">
                                    <XCircle size={11} /> {msg.error_code || "Failed"}
                                  </span>
                                )}
                              </span>
                            )}
                          </div>
                        </div>
                      </div>
                    );
                  })
                )}
              </div>

              {/* Message Composer Area */}
              <div className="p-3 border-t border-subtle bg-card space-y-2">
                {!isWindowOpen && (
                  <div className="bg-amber-500/10 border border-amber-500/20 rounded-lg p-2.5 flex items-start gap-2 text-amber-400 text-xs">
                    <AlertTriangle size={15} className="text-amber-500 flex-shrink-0 mt-0.5" />
                    <div>
                      <p className="font-bold">24-Hour Customer Window Expired</p>
                      <p className="text-[11px] text-muted mt-0.5">
                        Meta WhatsApp Cloud API policy forbids free-form replies after 24 hours of customer inactivity. Free-form dispatch is locked until the passenger replies or a pre-approved template message is dispatched.
                      </p>
                    </div>
                  </div>
                )}

                <div className="flex items-end gap-2">
                  <div className="flex-1 relative">
                    <textarea
                      rows={2}
                      disabled={!isWindowOpen || sendingMessage}
                      placeholder={
                        isWindowOpen
                          ? "Type WhatsApp response (Press Enter to send, Shift+Enter for newline)..."
                          : "Free-form messaging disabled (24h customer window expired)"
                      }
                      value={messageInput}
                      onChange={e => setMessageInput(e.target.value)}
                      onKeyDown={e => {
                        if (e.key === 'Enter' && !e.shiftKey) {
                          e.preventDefault();
                          handleSendMessage();
                        }
                      }}
                      className="w-full bg-input border border-subtle rounded-xl p-2.5 text-xs text-main placeholder-muted focus:outline-none focus:border-strong transition resize-none disabled:opacity-50"
                    />
                    <div className="absolute right-2.5 bottom-2 text-[9px] text-muted font-mono pointer-events-none">
                      {messageInput.length} / 4096
                    </div>
                  </div>

                  <button
                    onClick={handleSendMessage}
                    disabled={!isWindowOpen || sendingMessage || !messageInput.trim()}
                    className="p-3 bg-primary hover:bg-primary/90 text-white rounded-xl transition shadow-md disabled:opacity-40 disabled:hover:bg-primary flex items-center justify-center flex-shrink-0"
                  >
                    {sendingMessage ? (
                      <Loader2 size={16} className="animate-spin" />
                    ) : (
                      <Send size={16} />
                    )}
                  </button>
                </div>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
}
