'use client';

import React, { useState, useEffect, useCallback } from 'react';
import Link from 'next/link';
import {
  Brain,
  Sparkles,
  Activity,
  CheckCircle2,
  AlertTriangle,
  Clock,
  RefreshCw,
  HelpCircle,
  TrendingUp,
  ShieldCheck,
  ShieldAlert,
  ArrowRight,
  Filter,
  Layers,
  Database,
  Cpu,
  Compass,
  GitPullRequest,
  Check,
  XCircle,
  ExternalLink,
  ChevronDown,
  ChevronUp
} from 'lucide-react';
import { fetchWithAuth } from '@/lib/fetchWithAuth';

export type CanonicalLearningState = 'COLLECTING' | 'LEARNING' | 'VERIFIED' | 'ACTIVE' | 'REJECTED' | 'QUARANTINED';
export type ConfidenceLevel = 'HIGH' | 'MEDIUM' | 'LOW' | 'UNTRUSTED';

export interface SubsystemLearningCard {
  id: string;
  name: string;
  category: string;
  status: 'ONLINE' | 'CALIBRATING' | 'OFFLINE';
  learningState: CanonicalLearningState;
  sampleCount: number;
  confidence: ConfidenceLevel;
  confidenceScore: number;
  freshness: string;
  isProductionActive: boolean;
  consumedBy: string[];
  impactType: string;
  lastUpdated: string;
  description: string;
  lowSampleWarning: boolean;
}

export interface WhatWeLearnedHighlight {
  id: string;
  subsystem: string;
  title: string;
  keyMetric: string;
  summary: string;
  observations: number;
  confidence: ConfidenceLevel;
  productionConsumer: string;
  lastUpdated: string;
  evidence: Record<string, any>;
}

export interface RejectedSignalItem {
  id: string;
  subsystem: string;
  reason: 'LOW_SAMPLE' | 'VALIDATION_FAILURE' | 'PENDING_APPROVAL' | 'SPAM_FLAGGED' | 'STALE_DATA';
  description: string;
  source: string;
  timestamp: string;
  metadata?: Record<string, any>;
}

export interface LearningTimelineEvent {
  id: string;
  timestamp: string;
  subsystem: string;
  event: string;
  status: CanonicalLearningState;
  confidence: ConfidenceLevel;
  detail: string;
}

export interface IntelligenceHealthOverview {
  activeSystemsCount: number;
  totalSystemsCount: number;
  eventsCollectedTotal: number;
  samplesAvailableTotal: number;
  itemsLearnedTotal: number;
  itemsVerifiedTotal: number;
  itemsActiveTotal: number;
  itemsRejectedTotal: number;
  itemsQuarantinedTotal: number;
  lastLearningUpdate: string;
  overallHealth: 'HEALTHY' | 'CALIBRATING' | 'DEGRADED';
}

export interface LearningIntelligenceData {
  overview: IntelligenceHealthOverview;
  subsystems: SubsystemLearningCard[];
  highlights: WhatWeLearnedHighlight[];
  rejectedSignals: RejectedSignalItem[];
  timeline: LearningTimelineEvent[];
  dataQuality: {
    staleDataCount: number;
    sparseSampleCount: number;
    validationFailuresCount: number;
    diagnostics: string[];
  };
  glossary: Record<string, string>;
  generatedAt: string;
}

interface LearningIntelligencePanelProps {
  api: string;
  getAuthHeaders: () => Record<string, string>;
  triggerToast?: (message: string, type?: 'success' | 'error' | 'info') => void;
}

export function LearningIntelligencePanel({ api, getAuthHeaders, triggerToast }: LearningIntelligencePanelProps) {
  const [data, setData] = useState<LearningIntelligenceData | null>(null);
  const [loading, setLoading] = useState(true);
  const [showGlossary, setShowGlossary] = useState(false);
  const [activeFilter, setActiveFilter] = useState<'ALL' | 'ACTIVE' | 'QUARANTINED'>('ALL');

  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      const res = await fetchWithAuth(`${api}/api/admin/learning-intelligence`, {
        headers: getAuthHeaders()
      });
      const json = await res.json();
      if (json.success && json.data) {
        setData(json.data);
      } else {
        triggerToast?.(json.error || 'Failed to fetch learning observatory data', 'error');
      }
    } catch (err: any) {
      triggerToast?.(`Network error: ${err.message}`, 'error');
    } finally {
      setLoading(false);
    }
  }, [api, getAuthHeaders, triggerToast]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const overview = data?.overview || {
    activeSystemsCount: 7,
    totalSystemsCount: 7,
    eventsCollectedTotal: 0,
    samplesAvailableTotal: 0,
    itemsLearnedTotal: 0,
    itemsVerifiedTotal: 0,
    itemsActiveTotal: 0,
    itemsRejectedTotal: 0,
    itemsQuarantinedTotal: 0,
    lastLearningUpdate: new Date().toISOString(),
    overallHealth: 'HEALTHY'
  };

  const subsystems = data?.subsystems || [];
  const highlights = data?.highlights || [];
  const rejectedSignals = data?.rejectedSignals || [];
  const timeline = data?.timeline || [];
  const dataQuality = data?.dataQuality || {
    staleDataCount: 0,
    sparseSampleCount: 0,
    validationFailuresCount: 0,
    diagnostics: ['All statistical thresholds optimal.']
  };

  const filteredSubsystems = subsystems.filter(s => {
    if (activeFilter === 'ACTIVE') return s.isProductionActive;
    if (activeFilter === 'QUARANTINED') return s.learningState === 'QUARANTINED' || s.lowSampleWarning;
    return true;
  });

  const getConfidenceBadgeClass = (conf: ConfidenceLevel) => {
    switch (conf) {
      case 'HIGH':
        return 'badge-success';
      case 'MEDIUM':
        return 'badge-warning';
      case 'LOW':
        return 'badge-danger';
      default:
        return 'badge-danger';
    }
  };

  const getStateBadgeClass = (state: CanonicalLearningState) => {
    switch (state) {
      case 'ACTIVE':
        return 'badge-indigo';
      case 'VERIFIED':
        return 'badge-success';
      case 'LEARNING':
        return 'badge-info';
      case 'QUARANTINED':
        return 'badge-warning';
      case 'REJECTED':
        return 'badge-danger';
      default:
        return 'badge-neutral';
    }
  };

  return (
    <div className="space-y-6 text-main">
      {/* ── Header ─────────────────────────────────────────────────────────── */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <div className="flex items-center gap-2.5">
            <Brain className="text-purple-600 dark:text-purple-400" size={26} />
            <h2 className="text-2xl font-bold tracking-tight">Learning &amp; Intelligence Observatory</h2>
            <span
              className={`text-[10px] font-bold px-2 py-0.5 rounded-full uppercase ${
                overview.overallHealth === 'HEALTHY'
                  ? 'badge-success'
                  : 'badge-warning'
              }`}
            >
              {overview.overallHealth}
            </span>
          </div>
          <p className="text-sm text-muted mt-0.5">
            Comprehensive observability layer for platform machine learning, statistical validation, delay patterns &amp; routing memory.
          </p>
        </div>

        <div className="flex items-center gap-2.5">
          <button
            onClick={() => setShowGlossary(!showGlossary)}
            className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold rounded-lg bg-surface border border-subtle hover:border-strong text-main transition-all shadow-sm"
          >
            <HelpCircle size={14} className="text-purple-600 dark:text-purple-400" />
            <span>Metric Explanations</span>
            {showGlossary ? <ChevronUp size={13} /> : <ChevronDown size={13} />}
          </button>

          <button
            onClick={fetchData}
            disabled={loading}
            className="flex items-center gap-2 px-3 py-1.5 text-xs font-semibold rounded-lg bg-card border border-subtle hover:border-strong text-main transition-all shadow-sm"
          >
            <RefreshCw size={14} className={loading ? 'animate-spin text-primary' : ''} />
            Refresh
          </button>
        </div>
      </div>

      {/* ── Plain-English Explanation Glossary ──────────────────────────────── */}
      {showGlossary && data?.glossary && (
        <div className="p-4 rounded-xl border border-purple-200 dark:border-purple-800/40 bg-purple-50/70 dark:bg-purple-950/20 space-y-3">
          <div className="flex items-center gap-2 text-xs font-bold text-purple-800 dark:text-purple-300">
            <Sparkles size={15} />
            <span>Plain-English Intelligence Glossary (New Admin Guide)</span>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-3 text-xs">
            {Object.entries(data.glossary).map(([term, explanation]) => (
              <div key={term} className="p-3 rounded-lg bg-card border border-purple-100 dark:border-subtle space-y-1 shadow-sm">
                <div className="font-bold text-main">{term}</div>
                <div className="text-[11px] text-secondary leading-relaxed">{explanation}</div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ── Overview KPI Metric Bar ─────────────────────────────────────────── */}
      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-6 gap-3">
        {/* Active Systems */}
        <div className="bg-card p-3.5 rounded-xl border border-subtle shadow-sm">
          <div className="text-[11px] font-semibold text-muted">Active Systems</div>
          <div className="text-2xl font-black mt-0.5 text-main">
            {overview.activeSystemsCount} <span className="text-xs text-muted font-normal">/ {overview.totalSystemsCount}</span>
          </div>
          <div className="text-[10px] text-emerald-600 dark:text-emerald-400 mt-1 flex items-center gap-1 font-bold">
            <CheckCircle2 size={11} /> 100% Operational
          </div>
        </div>

        {/* Events Ingested */}
        <div className="bg-card p-3.5 rounded-xl border border-subtle shadow-sm">
          <div className="text-[11px] font-semibold text-muted">Events Collected</div>
          <div className="text-2xl font-black mt-0.5 text-indigo-600 dark:text-indigo-400">{overview.eventsCollectedTotal}</div>
          <div className="text-[10px] text-muted mt-1 font-medium">Raw telemetry inputs</div>
        </div>

        {/* Usable Samples */}
        <div className="bg-card p-3.5 rounded-xl border border-subtle shadow-sm">
          <div className="text-[11px] font-semibold text-muted">Samples Available</div>
          <div className="text-2xl font-black mt-0.5 text-purple-600 dark:text-purple-400">{overview.samplesAvailableTotal}</div>
          <div className="text-[10px] text-muted mt-1 font-medium">Confirmed data points</div>
        </div>

        {/* Verified Models */}
        <div className="bg-card p-3.5 rounded-xl border border-subtle shadow-sm">
          <div className="text-[11px] font-semibold text-muted">Items Verified</div>
          <div className="text-2xl font-black mt-0.5 text-emerald-600 dark:text-emerald-400">{overview.itemsVerifiedTotal}</div>
          <div className="text-[10px] text-muted mt-1 font-medium">Met sample floor (≥5)</div>
        </div>

        {/* Production Active */}
        <div className="bg-card p-3.5 rounded-xl border border-subtle shadow-sm">
          <div className="text-[11px] font-semibold text-muted">Production Active</div>
          <div className="text-2xl font-black mt-0.5 text-amber-600 dark:text-amber-400">{overview.itemsActiveTotal}</div>
          <div className="text-[10px] text-muted mt-1 font-medium">Influencing live traffic</div>
        </div>

        {/* Quarantined / Review */}
        <div className="bg-card p-3.5 rounded-xl border border-subtle shadow-sm">
          <div className="text-[11px] font-semibold text-muted">Quarantined / Review</div>
          <div className="text-2xl font-black mt-0.5 text-orange-600 dark:text-orange-400">{overview.itemsQuarantinedTotal}</div>
          <div className="text-[10px] text-muted mt-1 font-medium">Awaiting admin review</div>
        </div>
      </div>

      {/* ── Subsystem Filter Tabs ───────────────────────────────────────────── */}
      <div className="flex items-center justify-between gap-3 border-b border-subtle pb-2">
        <div className="flex items-center gap-2">
          <button
            onClick={() => setActiveFilter('ALL')}
            className={`px-3 py-1.5 text-xs font-bold rounded-lg transition-all ${
              activeFilter === 'ALL' ? 'bg-primary text-white shadow-sm' : 'text-muted hover:text-main'
            }`}
          >
            All Subsystems ({subsystems.length})
          </button>
          <button
            onClick={() => setActiveFilter('ACTIVE')}
            className={`px-3 py-1.5 text-xs font-bold rounded-lg transition-all ${
              activeFilter === 'ACTIVE' ? 'bg-primary text-white shadow-sm' : 'text-muted hover:text-main'
            }`}
          >
            Active in Production ({subsystems.filter(s => s.isProductionActive).length})
          </button>
          <button
            onClick={() => setActiveFilter('QUARANTINED')}
            className={`px-3 py-1.5 text-xs font-bold rounded-lg transition-all ${
              activeFilter === 'QUARANTINED' ? 'bg-primary text-white shadow-sm' : 'text-muted hover:text-main'
            }`}
          >
            Needs Attention ({subsystems.filter(s => s.learningState === 'QUARANTINED' || s.lowSampleWarning).length})
          </button>
        </div>

        <div className="text-xs text-muted font-mono hidden md:block">
          Last cycle: {new Date(overview.lastLearningUpdate).toLocaleTimeString()}
        </div>
      </div>

      {/* ── 7 Subsystems Grid ────────────────────────────────────────────────── */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filteredSubsystems.map(sub => (
          <div
            key={sub.id}
            className="bg-card p-5 rounded-xl border border-subtle shadow-sm flex flex-col justify-between space-y-3.5 hover:border-strong transition-all"
          >
            <div>
              {/* Card Header */}
              <div className="flex items-start justify-between gap-2">
                <div>
                  <div className="text-[10px] uppercase font-bold text-muted tracking-wider">{sub.category}</div>
                  <h3 className="text-sm font-bold text-main mt-0.5">{sub.name}</h3>
                </div>
                <span className={`text-[9px] font-bold px-2 py-0.5 rounded-full uppercase ${getStateBadgeClass(sub.learningState)}`}>
                  {sub.learningState}
                </span>
              </div>

              {/* Description */}
              <p className="text-[11px] text-secondary mt-2 leading-relaxed">{sub.description}</p>

              {/* Metric Metrics Grid */}
              <div className="grid grid-cols-2 gap-2 mt-3 pt-3 border-t border-subtle text-xs">
                <div className="p-2 rounded-lg bg-surface border border-subtle">
                  <div className="text-[10px] font-medium text-muted">Samples Available</div>
                  <div className="text-base font-black text-main mt-0.5 flex items-center gap-1.5">
                    <span>{sub.sampleCount}</span>
                    {sub.lowSampleWarning && (
                      <span className="text-[9px] font-bold badge-warning px-1.5 py-0.5 rounded">
                        &lt; 5 MIN
                      </span>
                    )}
                  </div>
                </div>

                <div className="p-2 rounded-lg bg-surface border border-subtle">
                  <div className="text-[10px] font-medium text-muted">Confidence Level</div>
                  <div className="mt-1">
                    <span className={`text-[10px] font-bold px-2 py-0.5 rounded uppercase ${getConfidenceBadgeClass(sub.confidence)}`}>
                      {sub.confidence} ({sub.confidenceScore}%)
                    </span>
                  </div>
                </div>
              </div>

              {/* Production Consumer */}
              <div className="mt-3 space-y-1 text-xs">
                <div className="text-[10px] font-bold text-muted">Production Consumers:</div>
                <div className="flex flex-wrap gap-1">
                  {sub.consumedBy.map((c, i) => (
                    <span key={i} className="text-[10px] px-2 py-0.5 rounded bg-surface border border-subtle font-mono text-secondary font-medium">
                      {c}
                    </span>
                  ))}
                </div>
              </div>
            </div>

            {/* Impact Footer */}
            <div className="pt-3 border-t border-subtle text-[11px] text-secondary flex items-start gap-1.5">
              <Sparkles size={13} className="text-primary shrink-0 mt-0.5" />
              <span className="leading-snug">{sub.impactType}</span>
            </div>
          </div>
        ))}
      </div>

      {/* ── "What Did We Learn?" Evidence Showcase ────────────────────────────── */}
      <div className="bg-card p-5 rounded-xl border border-subtle shadow-sm space-y-4">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="font-bold text-sm text-main flex items-center gap-2">
              <Sparkles size={16} className="text-amber-500 dark:text-amber-400" />
              What Did We Learn? (Real Evidence Showcase)
            </h3>
            <p className="text-xs text-muted mt-0.5">
              Human-readable summaries derived directly from live tracking, waitlist predictions, split interactions and routing memory.
            </p>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-3">
          {highlights.map(hl => (
            <div key={hl.id} className="p-3.5 rounded-xl bg-surface border border-subtle space-y-2">
              <div className="flex items-center justify-between text-[10px]">
                <span className="font-bold text-primary font-mono">{hl.subsystem}</span>
                <span className={`px-1.5 py-0.5 rounded font-bold uppercase ${getConfidenceBadgeClass(hl.confidence)}`}>
                  {hl.confidence}
                </span>
              </div>
              <h4 className="text-xs font-bold text-main">{hl.title}</h4>
              <div className="text-sm font-black text-amber-600 dark:text-amber-400">{hl.keyMetric}</div>
              <p className="text-[11px] text-secondary leading-relaxed">{hl.summary}</p>
              <div className="text-[10px] text-muted pt-2 border-t border-subtle flex justify-between">
                <span>Observed: {hl.observations} samples</span>
                <span>Consumer: {hl.productionConsumer}</span>
              </div>
            </div>
          ))}

          {highlights.length === 0 && (
            <div className="col-span-4 text-center py-8 text-muted text-xs">
              No highlighted intelligence samples recorded yet. Telemetry workers are actively collecting data.
            </div>
          )}
        </div>
      </div>

      {/* ── Rejected & Quarantined Signals ───────────────────────────────────── */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Rejected & Quarantined Signals Table */}
        <div className="bg-card p-5 rounded-xl border border-subtle shadow-sm space-y-3 flex flex-col justify-between">
          <div>
            <div className="flex items-center justify-between mb-3">
              <div>
                <h3 className="font-bold text-sm text-main flex items-center gap-2">
                  <ShieldAlert size={16} className="text-amber-500 dark:text-amber-400" />
                  Rejected &amp; Quarantined Signals ({rejectedSignals.length})
                </h3>
                <p className="text-xs text-muted mt-0.5">
                  Items held for review, sparse samples below statistical floor, or rejected telemetry outliers.
                </p>
              </div>
              <Link
                href="/admin/self-learning"
                className="text-[11px] font-bold text-primary hover:underline flex items-center gap-1"
              >
                Open Review Queue <ExternalLink size={12} />
              </Link>
            </div>

            <div className="space-y-2">
              {rejectedSignals.map(rej => (
                <div key={rej.id} className="p-3 rounded-lg bg-surface border border-subtle text-xs space-y-1">
                  <div className="flex items-center justify-between">
                    <span className="font-bold text-main">{rej.subsystem}</span>
                    <span
                      className={`text-[9px] font-bold px-1.5 py-0.5 rounded uppercase ${
                        rej.reason === 'PENDING_APPROVAL'
                          ? 'badge-warning'
                          : 'badge-danger'
                      }`}
                    >
                      {rej.reason}
                    </span>
                  </div>
                  <p className="text-[11px] text-secondary leading-relaxed">{rej.description}</p>
                  <div className="text-[10px] text-muted flex justify-between pt-1 font-mono">
                    <span>Source: {rej.source}</span>
                    <span>{new Date(rej.timestamp).toLocaleTimeString()}</span>
                  </div>
                </div>
              ))}

              {rejectedSignals.length === 0 && (
                <div className="text-center py-6 text-xs text-muted">
                  Zero rejected or quarantined items. Ingest streams passing all validation checks.
                </div>
              )}
            </div>
          </div>

          <div className="pt-3 border-t border-subtle text-[11px] text-muted">
            All rejected signals are preserved in observability logs without polluting production models.
          </div>
        </div>

        {/* Learning Activity Timeline */}
        <div className="bg-card p-5 rounded-xl border border-subtle shadow-sm space-y-3 flex flex-col justify-between">
          <div>
            <div className="flex items-center justify-between mb-3">
              <div>
                <h3 className="font-bold text-sm text-main flex items-center gap-2">
                  <Clock size={16} className="text-indigo-600 dark:text-indigo-400" />
                  Recent Learning Activity Timeline
                </h3>
                <p className="text-xs text-muted mt-0.5">Chronological record of recent model adaptations and verified records.</p>
              </div>
            </div>

            <div className="space-y-2.5">
              {timeline.map(event => (
                <div key={event.id} className="p-3 rounded-lg bg-surface border border-subtle text-xs space-y-1">
                  <div className="flex items-center justify-between">
                    <span className="font-bold text-main flex items-center gap-1.5">
                      <span className="w-1.5 h-1.5 rounded-full bg-primary" />
                      {event.event}
                    </span>
                    <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded uppercase ${getStateBadgeClass(event.status)}`}>
                      {event.status}
                    </span>
                  </div>
                  <div className="text-[11px] text-secondary">{event.detail}</div>
                  <div className="text-[10px] text-muted flex justify-between pt-1 font-mono">
                    <span>{event.subsystem}</span>
                    <span>{new Date(event.timestamp).toLocaleTimeString()}</span>
                  </div>
                </div>
              ))}

              {timeline.length === 0 && (
                <div className="text-center py-6 text-xs text-muted">
                  No learning activity recorded in the current session window.
                </div>
              )}
            </div>
          </div>

          <div className="pt-3 border-t border-subtle text-[11px] text-muted flex items-center justify-between">
            <span>Diagnostics: {dataQuality.diagnostics[0] || 'System Healthy'}</span>
          </div>
        </div>
      </div>
    </div>
  );
}
